<!DOCTYPE html>
<html lang="en">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Settings | Health Center Admin</title><link rel="stylesheet" href="https://maxcdn.bootstrapcdn.com/bootstrap/3.4.1/css/bootstrap.min.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/4.7.0/css/font-awesome.min.css"><link rel="stylesheet" href="../css/admin.css"></head>
<body class="admin-page" data-title="Settings"><main class="admin-content">
  <section class="admin-card settings-card">
    <ul class="nav nav-tabs admin-settings-tabs" role="tablist"><li class="active"><a href="#general" role="tab" data-toggle="tab">General</a></li><li><a href="#profile" role="tab" data-toggle="tab">Profile</a></li><li><a href="#notifications" role="tab" data-toggle="tab">Notifications</a></li></ul>
    <div class="tab-content admin-settings-content">
      <div class="tab-pane active" id="general"><form class="save-form"><h2>Hospital Information</h2><div class="row">
        <div class="col-sm-6 form-group"><label>Hospital Name</label><input class="form-control" value="Health Center"></div><div class="col-sm-6 form-group"><label>Phone</label><input class="form-control" value="010-060-0160"></div><div class="col-sm-6 form-group"><label>Email</label><input class="form-control" type="email" value="info@company.com"></div><div class="col-sm-6 form-group"><label>Opening Hours</label><input class="form-control" value="Mon-Fri 06:00 AM - 10:00 PM"></div><div class="col-sm-12 form-group"><label>Address</label><textarea class="form-control" rows="3">123 Wellness Avenue, New York, NY</textarea></div>
      </div><button class="btn btn-admin-primary" type="submit">Save Changes</button></form></div>
      <div class="tab-pane" id="profile"><form class="save-form"><h2>Admin Profile</h2><div class="row">
        <div class="col-sm-6 form-group"><label>Name</label><input class="form-control" value="Admin"></div><div class="col-sm-6 form-group"><label>Email</label><input class="form-control" type="email" value="admin@healthcenter.com"></div><div class="col-sm-6 form-group"><label>Current Password</label><input class="form-control" type="password" placeholder="Current password"></div><div class="col-sm-6 form-group"><label>New Password</label><input class="form-control" type="password" placeholder="New password"></div>
      </div><button class="btn btn-admin-primary" type="submit">Save Changes</button></form></div>
      <div class="tab-pane" id="notifications"><form class="save-form"><h2>Notification Preferences</h2><div class="notification-option"><div><strong>New appointment requests</strong><small>Get notified when a patient books an appointment.</small></div><label class="admin-switch"><input type="checkbox" checked><span></span></label></div><div class="notification-option"><div><strong>New patient registrations</strong><small>Get notified when a new patient joins the portal.</small></div><label class="admin-switch"><input type="checkbox" checked><span></span></label></div><div class="notification-option"><div><strong>Weekly reports</strong><small>Receive a weekly summary of center activity.</small></div><label class="admin-switch"><input type="checkbox"><span></span></label></div><button class="btn btn-admin-primary" type="submit">Save Changes</button></form></div>
    </div>
  </section>
</main><script src="https://ajax.googleapis.com/ajax/libs/jquery/1.12.4/jquery.min.js"></script><script src="https://maxcdn.bootstrapcdn.com/bootstrap/3.4.1/js/bootstrap.min.js"></script><script src="../js/admin.js"></script></body></html>
